mapper.delete:
delete from kb_chunk



        and 1 = 0

     and subject_id = #{subjectId}
     and chapter_id = #{chapterId}
     and source_type = #{sourceType}
     and doc_id = #{docId}

mapper.select:
select id from kb_chunk

     and subject_id = #{subjectId}
     and chapter_id = #{chapterId}

        and source_type in

            #{type}



order by id asc

select distinct doc_id from kb_chunk

     and subject_id = #{subjectId}
     and chapter_id = #{chapterId}

select doc_id as docId, chunk_index as chunkIndex, content_hash as contentHash
from kb_chunk

     and subject_id = #{subjectId}
     and chapter_id = #{chapterId}

select ,
       match(title, content) against(#{keyword} in natural language mode) as keyword_score
from kb_chunk
where match(title, content) against(#{keyword} in natural language mode)
  and status = 1
   and subject_id = #{subjectId}
   and chapter_id = #{chapterId}

      and source_type in

          #{type}


order by keyword_score desc
limit #{limit}

select source_type as sourceType, count(1) as total from kb_chunk
and subject_id = #{subjectId}
group by source_type
